        t_enumerator?.Dispose();
        t_enumerator = _stackWalk
            .CreateStackWalk(_threadData, contextBuffer, isFirst)
            .Where(h => h.State is not (StackWalkState.Frame or StackWalkState.SkippedFrame))
            .GetEnumerator();
        Current = t_enumerator is not null && t_enumerator.MoveNext() ? t_enumerator.Current : null;
